begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(7);
insert into auth.users (id, email) values ('90000000-0000-4000-8000-000000000001', 'owner@example.com'), ('90000000-0000-4000-8000-000000000002', 'stranger@example.com');
insert into public.admin_users (user_id, role, is_active) values ('90000000-0000-4000-8000-000000000001', 'owner', true);
insert into public.categories (id, name, slug, status) values ('91000000-0000-4000-8000-000000000001', 'Sweet', 'sweet', 'published');
insert into public.products (id, category_id, name, slug, base_price_cents, status, is_available) values ('92000000-0000-4000-8000-000000000001', '91000000-0000-4000-8000-000000000001', 'Pastry', 'pastry', 500, 'published', true);
insert into public.product_option_groups (id, product_id, name, selection_type, status) values ('95000000-0000-4000-8000-000000000001', '92000000-0000-4000-8000-000000000001', 'Flavour', 'single', 'published');
insert into public.product_option_values (id, option_group_id, name, price_delta_cents, status, is_available) values ('96000000-0000-4000-8000-000000000001', '95000000-0000-4000-8000-000000000001', 'Vanilla', 0, 'published', true), ('96000000-0000-4000-8000-000000000002', '95000000-0000-4000-8000-000000000001', 'Owner draft', 100, 'draft', false);
set local role anon;
select results_eq($$select name from public.product_option_values where id in ('96000000-0000-4000-8000-000000000001', '96000000-0000-4000-8000-000000000002') order by name$$, array['Vanilla'], 'anonymous visitors see published values only');
select throws_ok($$insert into public.product_option_values (option_group_id, name) values ('95000000-0000-4000-8000-000000000001', 'Unsafe')$$, '42501', null, 'anonymous visitors cannot create values');
set local role authenticated;
set local request.jwt.claim.sub = '90000000-0000-4000-8000-000000000002';
select results_eq($$select name from public.product_option_values where id in ('96000000-0000-4000-8000-000000000001', '96000000-0000-4000-8000-000000000002') order by name$$, array['Vanilla'], 'a non-owner sees published values only');
select is_empty($$update public.product_option_values set price_delta_cents = 1 where id = '96000000-0000-4000-8000-000000000001' returning id$$, 'a non-owner cannot alter a price');
set local request.jwt.claim.sub = '90000000-0000-4000-8000-000000000001';
select results_eq($$select name from public.product_option_values where id in ('96000000-0000-4000-8000-000000000001', '96000000-0000-4000-8000-000000000002') order by name$$, array['Owner draft', 'Vanilla'], 'the owner sees all value states');
select results_eq($$update public.product_option_values set price_delta_cents = 250 where id = '96000000-0000-4000-8000-000000000002' returning price_delta_cents$$, array[250], 'the owner changes an additional price');
reset role;
select results_eq($$select price_delta_cents from public.product_option_values where id = '96000000-0000-4000-8000-000000000001'$$, array[0], 'the denied price change did not persist');
select * from finish();
rollback;
